(
    "assetClass"  TEXT PRIMARY KEY,
    years         NUMERIC NOT NULL
);
INSERT INTO class_default_life ("assetClass", years) VALUES
('Network Equipment', 5),
('Machinery', 7),
('Vehicles', 5),
('Buildings', 39),
('Other', 7)
ON CONFLICT ("assetClass") DO NOTHING;

-- ---------- Scenario Modeling defaults (was DEFAULT_SCENARIOS / DEFAULT_BASIS in routes/modeling.ts) ----------
CREATE TABLE IF NOT EXISTS modeling_scenarios
(
    id                     SERIAL PRIMARY KEY,
    label                  TEXT NOT NULL,
    method                 TEXT NOT NULL,
    "bonusPct"             NUMERIC NOT NULL DEFAULT 0,
    "recoveryPeriodYears"  NUMERIC NOT NULL DEFAULT 0,
    "sortOrder"            INTEGER NOT NULL DEFAULT 0,
    active                 BOOLEAN NOT NULL DEFAULT TRUE
);
INSERT INTO modeling_scenarios (label, method, "bonusPct", "recoveryPeriodYears", "sortOrder")
SELECT * FROM (VALUES
('Scenario A — Baseline', 'MACRS ADS', 0, 5, 0),
('Scenario B — Bonus', 'MACRS 200% DB', 100, 5, 1),
('Scenario C — Elect ADS', 'Straight-Line', 0, 7, 2)
) AS v(label, method, "bonusPct", "recoveryPeriodYears", "sortOrder")
WHERE NOT EXISTS (SELECT 1 FROM modeling_scenarios);

INSERT INTO app_settings (key, value) VALUES
('modelingBasis', '1000000'),
('defaultRecoveryYears', '7')
ON CONFLICT (key) DO NOTHING;

-- ---------- Asset form "Depreciation Method" dropdown (was METHODS in client AssetForm.jsx) ----------
INSERT INTO form_option_lists (list, value, "sortOrder")
SELECT * FROM (VALUES
('assetMethod', 'MACRS ADS', 0),
('assetMethod', 'MACRS 200% DB', 1),
('assetMethod', 'Straight-Line', 2)
) AS v(list, value, "sortOrder")
WHERE NOT EXISTS (SELECT 1 FROM form_option_lists WHERE list = 'assetMethod');

